from pathlib import Path
import collections,hashlib,json,os,sys,time
ROOT=Path('/Users/sunjaekim/Developer/oil_level_tracker');sys.path[:0]=[str(ROOT),str(ROOT/'src')]
os.environ.setdefault('MPLCONFIGDIR','/tmp/s11-reference-layout-mpl')
import cv2
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from oil_tracker.adapters.vision import temporal_raster_evidence as temporal
OUT=ROOT/'sample/output/s11-reference-layout-20261009-001';OUT.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,obj):(OUT/name).write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
record_path=ROOT/'docs/50-diagnostics/s11/2026-10-09-observed-edge-fragments.json'
prior=json.loads(record_path.read_text());cases={c['case_id']:c for c in prior['preflight']['cases']}
inputs={str(record_path.relative_to(ROOT)):sha(record_path)}
for c in cases.values():
    name=c.get('arrays_path') or c['images']['original_roi'];inputs[name]=prior['preflight']['inputs'][name]
sources={str(p.relative_to(ROOT)):sha(p) for p in (ROOT/'src').rglob('*.py')}
pairs=[]
for group,states in [('s5',['empty','inclined','settled']),('s6',['empty','forming','layer']),('s7',['empty','pouring','settled'])]:
    for scale in ['native','height_200']:
        for state in states:pairs.append([f'{group}-empty-{scale}',f'{group}-{state}-{scale}'])
for a,b in [(450,450),(420,450),(450,480),(1620,1635),(1635,1665),(1665,1680)]:pairs.append([f's4-f{a}',f's4-f{b}'])
SPEC={'operation':'Classical SIFT reciprocal descriptor matches, deduplicated exact source/destination XY; one shared translation/affine/projective mapping of all reference parts. No independently chosen side shifts.',
 'sift':{'nfeatures':512,'nOctaveLayers':3,'contrastThreshold':0.04,'edgeThreshold':10,'sigma':1.6},
 'ratio':0.75,'match_ties':'strict ratio, reciprocal matching, exact location deduplication by ratio/distance',
 'robust_fit':{'method':'RANSAC','reprojection_threshold_working_px':3.0,'iterations':2000,'confidence':0.99,'seed':20261009},
 'heldout':'two folds, alternating unique source locations in Y/X order; fit transform on train only, report every heldout residual without an acceptance threshold. Correlated geometric diagnostics, not independent efficacy trials.',
 'limits':'A shared mapping is appearance geometry, not camera truth or physical identity. Nonmatches are not occlusion/new fluid. A global projective model is not a general refractive model. Explicit local-warp and opaque-occluder controls test confounding. Raw descriptor support is not certified clear by center visibility.',
 'physical_decision':'NOT_EVALUATED','models':['translation','affine','projective'],'max_pixels':4194304}
pre={'schema':'s11-reference-layout-preflight-v1','base_head':'9f8dfe767e723482e395ee6b86dd798b5c4db734','spec':SPEC,'pairs':pairs,
 'inputs':inputs,'source_pins':sources,'cases':list(cases.values()),'runner_sha256':sha(Path(__file__)),
 'controls':['identical','translated','affine','opaque_center','smooth_local_warp','blank','repeated_pattern'],
 'stop_rule':'No threshold/feature-count/scale/mask tuning after observation; weak support or multiple explanations do not grant authority. Proceed to bounded source inspection or a necessary human physical question, not a match-to-fluid classifier.',
 'purpose':'Establish whether multiple related reference features support a common mapping and locate correspondence/visibility ambiguities before designing a physical rule.',
 'partition':'development','video_decode':False,'production_change':False,'ml_used':False,'descriptor_context':'raw fixed crop; no material/glare eligibility is claimed'}
for name,pin in {**inputs,**sources}.items():assert sha(ROOT/name)==pin
write('preflight.json',pre);(OUT/'run.py').write_bytes(Path(__file__).read_bytes())
cv2.setNumThreads(1)

def project(points,matrix):
    p=np.c_[points,np.ones(len(points))]@matrix.T
    return np.divide(p[:,:2],p[:,2:],out=np.full((len(p),2),np.nan),where=np.abs(p[:,2:])>1e-12)

def fit(a,b,kind):
    n=len(a);minimum={'translation':1,'affine':3,'projective':4}[kind]
    if n<minimum:return None,'insufficient_points'
    cv2.setRNGSeed(20261009)
    if kind=='translation':
        H=np.eye(3);H[:2,2]=np.median(b-a,axis=0)
    elif np.linalg.matrix_rank(np.c_[a,np.ones(n)])<3:return None,'collinear_source'
    elif kind=='affine':
        m,_=cv2.estimateAffine2D(a,b,method=cv2.RANSAC,ransacReprojThreshold=3.,maxIters=2000,confidence=.99,refineIters=10)
        if m is None:return None,'fit_failed'
        H=np.vstack((m,[0.,0.,1.]))
    else:
        H,_=cv2.findHomography(a,b,method=cv2.RANSAC,ransacReprojThreshold=3.,maxIters=2000,confidence=.99)
        if H is None:return None,'fit_failed'
    if not np.isfinite(H).all() or np.linalg.matrix_rank(H)<3:return None,'singular_or_nonfinite'
    return H,'MEASURED'

def stats(errors):
    if not len(errors) or not np.isfinite(errors).all():return None
    return {'count':len(errors),'median_px':float(np.median(errors)),'p90_px':float(np.quantile(errors,.9)),'max_px':float(errors.max())}

def measure(ref,cur):
    assert ref.shape==cur.shape and ref.dtype==cur.dtype==np.uint8 and ref.ndim==3 and ref.shape[2]==3
    assert ref.shape[0]*ref.shape[1]<=SPEC['max_pixels']
    gray=[cv2.cvtColor(p,cv2.COLOR_BGR2GRAY) for p in [ref,cur]]
    sift=cv2.SIFT_create(**SPEC['sift']);features=[sift.detectAndCompute(g,None) for g in gray]
    kp0,d0=features[0];kp1,d1=features[1];matches=[];ratio_count=0
    if d0 is not None and d1 is not None and len(d0)>=2 and len(d1)>=2:
        matcher=cv2.BFMatcher(cv2.NORM_L2)
        forward=matcher.knnMatch(d0,d1,k=2);backward=matcher.knnMatch(d1,d0,k=2)
        def accepted(rows):return {r[0].queryIdx:(r[0].trainIdx,r[0].distance,r[0].distance/r[1].distance) for r in rows if len(r)==2 and r[0].distance<.75*r[1].distance}
        f=accepted(forward);b=accepted(backward)
        eligible=[(i,j,dist,ratio) for i,(j,dist,ratio) in f.items() if j in b and b[j][0]==i]
        ratio_count=len(eligible);seen0=set();seen1=set()
        for i,j,dist,ratio in sorted(eligible,key=lambda r:(r[3],r[2],r[0],r[1])):
            a,c=tuple(kp0[i].pt),tuple(kp1[j].pt)
            if a in seen0 or c in seen1:continue
            seen0.add(a);seen1.add(c);matches.append({'ref_xy':list(a),'current_xy':list(c),'distance':dist,'ratio':ratio,'ref_keypoint_index':i,'current_keypoint_index':j})
    matches.sort(key=lambda r:(r['ref_xy'][1],r['ref_xy'][0]))
    a=np.array([r['ref_xy'] for r in matches],np.float64).reshape(-1,2);b=np.array([r['current_xy'] for r in matches],np.float64).reshape(-1,2)
    models={}
    for kind in SPEC['models']:
        H,state=fit(a,b,kind);entry={'status':state,'matrix':H.tolist() if H is not None else None,'folds':[]}
        if H is not None:
            predicted=project(a,H);errors=np.linalg.norm(predicted-b,axis=1)
            entry.update(predicted_xy=predicted.tolist(),errors_px=errors.tolist(),summary=stats(errors),within_ransac_radius=int((errors<=3).sum()))
        for parity in [0,1]:
            train=np.arange(len(a))%2==parity;test=~train;T,s=fit(a[train],b[train],kind)
            fold={'train_parity':parity,'train_indices':np.flatnonzero(train).tolist(),'test_indices':np.flatnonzero(test).tolist(),'status':s,'matrix':T.tolist() if T is not None else None}
            if T is not None:
                e=np.linalg.norm(project(a[test],T)-b[test],axis=1);fold.update(errors_px=e.tolist(),summary=stats(e))
            entry['folds'].append(fold)
        models[kind]=entry
    phase={};temporal._translation(gray[0].astype(np.float32),gray[1].astype(np.float32),np.ones(gray[0].shape,bool),diagnostics=phase)
    return {'keypoint_counts':[len(kp0),len(kp1)],'reciprocal_ratio_matches':ratio_count,'unique_location_matches':len(matches),
      'matches':matches,'models':models,'existing_phase_translation':phase,'physical_decision':'NOT_EVALUATED','selected_front':None}

def synth():
    rng=np.random.default_rng(20261009);ref=np.zeros((192,256,3),np.uint8)
    for y in range(12,180,20):
        for x in range(12,244,20):
            patch=rng.integers(0,256,(13,13,3),np.uint8);ref[y:y+13,x:x+13]=cv2.GaussianBlur(patch,(3,3),0)
    H=np.array([[1.01,.035,4.],[-.02,.985,7.],[0,0,1.]])
    cur=ref.copy();cur[50:145,65:195]=[120,150,180]
    yy,xx=np.indices(ref.shape[:2],dtype=np.float32);dx=12*np.exp(-((xx-128)**2+(yy-96)**2)/(2*50**2))
    patterned=np.tile(ref[12:32,12:32],(10,13,1))[:192,:256].copy()
    controls={'identical':ref,'translated':cv2.warpAffine(ref,np.array([[1,0,7],[0,1,-5]],float),(256,192)),
      'affine':cv2.warpPerspective(ref,H,(256,192)),'opaque_center':cur,
      'smooth_local_warp':cv2.remap(ref,xx-dx,yy,cv2.INTER_LINEAR),'blank':np.full_like(ref,127),'repeated_pattern':patterned}
    results=[]
    for name,target in controls.items():
        source=patterned if name=='repeated_pattern' else ref
        r=measure(source,target)
        if name=='identical':assert r['unique_location_matches']>=20 and r['models']['affine']['summary']['max_px']<1e-4
        if name=='translated':assert r['unique_location_matches']>=20 and np.linalg.norm(np.array(r['models']['translation']['matrix'])[:2,2]-[7,-5])<1
        if name=='affine':assert r['unique_location_matches']>=20 and np.max(np.linalg.norm(project(np.array([[40.,40.],[210.,40.],[210.,155.],[40.,155.]]),np.array(r['models']['affine']['matrix']))-project(np.array([[40.,40.],[210.,40.],[210.,155.],[40.,155.]]),H),axis=1))<2
        if name=='blank':assert r['unique_location_matches']==0
        r.update(control=name,arithmetic_status='PASS');results.append(r)
        cv2.imwrite(str(OUT/('synthetic-'+name+'.png')),target)
    return results

synthetic=synth();write('synthetic.json',synthetic)
cache={}
def load(case_id):
    if case_id not in cache:
        c=cases[case_id]
        if 'arrays_path' in c:
            with np.load(ROOT/c['arrays_path'],allow_pickle=False) as a:cache[case_id]=a['crop'].copy()
        else:cache[case_id]=cv2.imread(str(ROOT/c['images']['original_roi']))
    return cache[case_id]
results=[]
for a,b in pairs:
    ref,cur=load(a),load(b);start=time.perf_counter();r=measure(ref,cur);r.update(reference=a,current=b,seconds=time.perf_counter()-start)
    results.append(r)
    print(a,'->',b,'keypoints',r['keypoint_counts'],'matches',r['unique_location_matches'],flush=True)
    fig,axs=plt.subplots(1,2,figsize=(12,6),layout='constrained')
    for ax,p,title in zip(axs,[ref,cur],[a,b]):ax.imshow(cv2.cvtColor(p,cv2.COLOR_BGR2RGB));ax.set_title(title);ax.set_xlabel('working X');ax.set_ylabel('working Y')
    for i,m in enumerate(r['matches']):
        color=plt.get_cmap('hsv')((i%37)/37)
        for ax,k in zip(axs,['ref_xy','current_xy']):
            x,y=m[k];ax.plot(x,y,'o',ms=3,color=color)
            if i<80:ax.text(x,y,str(i),fontsize=5,color=color)
    fig.suptitle(f'Joint reference layout: {r["unique_location_matches"]} reciprocal location pairs; not physical correspondence\nAll points shown; numeric labels on first 80 only; no mask or fluid decision')
    fig.savefig(OUT/(a+'--'+b+'.png'),dpi=110,bbox_inches='tight');plt.close(fig)
for name,pin in {**inputs,**sources}.items():assert sha(ROOT/name)==pin,name
write('readout.json',{'schema':'s11-reference-layout-readout-v1','preflight_sha256':sha(OUT/'preflight.json'),
 'results':results,'synthetic':synthetic,'input_and_source_preserved':True,'physical_decision':'NOT_EVALUATED',
 'runtime':{'opencv':cv2.__version__,'numpy':np.__version__},
 'figures':{str(p.relative_to(ROOT)):sha(p) for p in sorted(OUT.glob('*.png'))}})
print('COMPLETE',OUT,flush=True)
